const wc = $('When Called').first().json;
let manifest = wc.image_manifest;
if (typeof manifest === 'string') { try { manifest = JSON.parse(manifest || '[]'); } catch (e) { manifest = []; } }
if (!Array.isArray(manifest)) manifest = [];
const out = [];
for (const m of manifest) {
  out.push({ json: { b64: m.b64 || '', mime: m.mime || 'image/png', placeholder_id: m.placeholder_id, caption: m.caption || '', alt: m.alt || '' } });
}
return out;

const manifest = $('Parse Manifest').all().map(i => i.json);
const uploads = items.map(i => i.json);
const map = {};
let failed = 0;
for (let i = 0; i < manifest.length; i++) {
  const ph = manifest[i].placeholder_id;
  const up = uploads[i];
  if (up && up.id && up.url) { map[ph] = { id: up.id, url: up.url }; }
  else { failed++; }
}
const attachment_ids = Object.values(map).map(v => v.id);
return [{ json: { upload_map: map, attachment_ids, failed_count: failed } }];

const wc = $('When Called').first().json;
let ops = wc.rendered_delta;
if (typeof ops === 'string') { try { ops = JSON.parse(ops || '[]'); } catch (e) { ops = []; } }
if (!Array.isArray(ops)) ops = [];
const agg = $('Aggregate Uploads').first().json;
const map = agg.upload_map || {};
const out = [];
const reviewer = Number(wc.reviewer_user_id);
if (reviewer) { out.push({ type: 'tag', user: { id: reviewer } }); out.push({ text: '\n' }); }
for (const op of ops) {
  if (op && op.type === 'image_ref') {
    const m = map[op.placeholder_id];
    if (m && m.id) out.push({ type: 'attachment', attachment: { id: m.id, url: m.url } });
    else out.push({ text: '[obraz niedostępny]\n', attributes: { italic: true } });
  } else {
    out.push(op);
  }
}
return [{ json: { ops: out, attachment_ids: agg.attachment_ids || [], failed_count: agg.failed_count || 0 } }];

const wc = $('When Called').first().json;
const ops = Array.isArray($json.ops) ? $json.ops : [];
let manifest = wc.image_manifest;
if (typeof manifest === 'string') { try { manifest = JSON.parse(manifest || '[]'); } catch (e) { manifest = []; } }
if (!Array.isArray(manifest)) manifest = [];

// Attribution footer (Block 11): name model per modality (text + image) + aggregate cost.
const textModel = wc.model || '—';
let imgModels = wc.image_models;
if (typeof imgModels === 'string') { try { imgModels = JSON.parse(imgModels); } catch (e) { imgModels = imgModels ? [imgModels] : []; } }
imgModels = Array.isArray(imgModels) ? imgModels.filter(Boolean) : [];
const totalCost = (Number(wc.cost_pln || 0) + Number(wc.total_image_cost_pln || 0)).toFixed(4);
const attribution = imgModels.length
  ? ('Przygotowane przez agenta AI (tekst: ' + textModel + ', obraz: ' + imgModels.join(', ') + '; koszt łączny: ' + totalCost + ' PLN). Do weryfikacji — nie finalizuje zadania.')
  : ('Przygotowane przez agenta AI (model: ' + textModel + ', koszt: ' + totalCost + ' PLN). Do weryfikacji — nie finalizuje zadania.');
const out = ops.slice();
let webSources = [];
try { const raw = wc.web_sources; webSources = Array.isArray(raw) ? raw : (raw ? JSON.parse(raw) : []); } catch(e) {}
if (webSources.length) {
  out.push({ text: 'Źródła' });
  out.push({ text: '\n', attributes: { header: 2 } });
  for (const s of webSources) {
    out.push({ text: (s.title || s.url), attributes: { link: s.url } });
    out.push({ text: '\n', attributes: { list: 'bullet' } });
  }
}
out.push({ text: '\n—\n' });
out.push({ text: attribution, attributes: { italic: true } });
out.push({ text: '\n' });
const payloadStr = JSON.stringify({ rendered_comment: out, image_manifest: manifest });
let bytes;
try { bytes = Buffer.byteLength(payloadStr, 'utf8'); } catch (e) { bytes = payloadStr.length; }
const fmt = bytes >= 1048576 ? (bytes / 1048576).toFixed(2).replace('.', ',') + ' MB' : Math.max(1, Math.round(bytes / 1024)) + ' KB';
out.push({ text: '\nrozmiar danych przebiegu: ' + fmt + '\n', attributes: { italic: true } });
const sp = (() => { try { return $('Get Spend Status').first().json || {}; } catch(e){ return {}; } })();
if (sp && sp.warn) {
  const uPct = Math.round(Number(sp.user_ratio||0)*100), cPct = Math.round(Number(sp.company_ratio||0)*100);
  const uStr = '⚠️ Wykorzystano ' + uPct + '% Twojego dziennego limitu wydatków (' + Number(sp.user_spend||0).toFixed(2) + ' / ' + Number(sp.user_limit||0).toFixed(2) + ' PLN).';
  const cStr = '⚠️ Wykorzystano ' + cPct + '% firmowego dziennego limitu wydatków (' + Number(sp.company_spend||0).toFixed(2) + ' / ' + Number(sp.company_limit||0).toFixed(2) + ' PLN).';
  if (sp.warn_reason === 'company') out.push({ text: '\n' + cStr + '\n', attributes: { italic: true } });
  else if (sp.warn_reason === 'both') out.push({ text: '\n' + uStr + '\n' + cStr + '\n', attributes: { italic: true } });
  else out.push({ text: '\n' + uStr + '\n', attributes: { italic: true } });
}
return { json: { ops: out, run_payload_bytes: bytes, attachment_ids: $json.attachment_ids || [] } };

// Block 12: no-upload delta path (manifest empty: text-only or embed-only result).
// Uses the resolver's rendered_delta directly; prepends the reviewer @-mention (parity with
// Build Comment / Rewrite Delta). image_ref ops are not expected here (those imply a manifest),
// but are handled defensively.
const wc = $('When Called').first().json;
let ops = wc.rendered_delta;
if (typeof ops === 'string') { try { ops = JSON.parse(ops || '[]'); } catch (e) { ops = []; } }
if (!Array.isArray(ops)) ops = [];
const out = [];
const reviewer = Number(wc.reviewer_user_id);
if (reviewer) { out.push({ type: 'tag', user: { id: reviewer } }); out.push({ text: '\n' }); }
for (const op of ops) {
  if (op && op.type === 'image_ref') { out.push({ text: '[obraz niedostępny]\n', attributes: { italic: true } }); }
  else { out.push(op); }
}
return [{ json: { ops: out, attachment_ids: [], failed_count: 0 } }];

const wc = $('When Called').first().json;
let docs = wc.doc_attachments;
if (typeof docs === 'string') { try { docs = JSON.parse(docs || '[]'); } catch (e) { docs = []; } }
if (!Array.isArray(docs)) docs = [];
const out = [];
for (let i = 0; i < docs.length; i++) {
  const d = docs[i] || {};
  out.push({ json: { file_id: d.file_id || '', filename: d.filename || ('dokument-' + (i+1)), mime: d.mime || 'application/octet-stream', idx: i } });
}
return out;

const items = $input.all();
const docs = $('Parse Docs').all();
const REQUIRED = {
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'xl/workbook.xml',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'word/document.xml',
  'application/vnd.openxmlformats-officedocument.presentationml.presentation': 'ppt/presentation.xml'
};
const out = [];
for (let k = 0; k < items.length; k++) {
  let srcIdx = 0;
  const pi = items[k].pairedItem;
  if (pi != null) srcIdx = (typeof pi === 'number') ? pi : (pi.item != null ? pi.item : 0);
  const meta = (docs[srcIdx] && docs[srcIdx].json) || {};
  const filename = meta.filename || 'dokument';
  const mime = meta.mime || '';
  let buf = null;
  try { buf = await this.helpers.getBinaryDataBuffer(k, 'data'); } catch (e) {}
  let valid = false, reason = '';
  if (!buf || buf.length < 200) {
    reason = 'plik pusty lub zbyt maly (' + (buf ? buf.length : 0) + ' B)';
  } else if (mime === 'application/pdf') {
    const head = buf.slice(0, 5).toString('latin1');
    const tail = buf.slice(Math.max(0, buf.length - 2048)).toString('latin1');
    if (head !== '%PDF-') reason = 'naglowek PDF nieprawidlowy';
    else if (tail.indexOf('%%EOF') < 0) reason = 'brak znacznika %%EOF (plik obciety?)';
    else if (buf.toString('latin1').indexOf('/Page') < 0) reason = 'brak stron w dokumencie PDF';
    else valid = true;
  } else if (REQUIRED[mime]) {
    const isZip = buf[0] === 0x50 && buf[1] === 0x4B && (buf[2] === 0x03 || buf[2] === 0x05 || buf[2] === 0x07);
    const latin = buf.toString('latin1');
    const hasEOCD = latin.indexOf('PK') >= 0;
    const hasCT = latin.indexOf('[Content_Types].xml') >= 0;
    const hasPart = latin.indexOf(REQUIRED[mime]) >= 0;
    if (!isZip) reason = 'nie jest archiwum ZIP/OOXML';
    else if (!hasEOCD) reason = 'uszkodzone archiwum (brak rekordu EOCD — plik obciety?)';
    else if (!hasCT) reason = 'brak [Content_Types].xml';
    else if (!hasPart) reason = 'brak wymaganej czesci ' + REQUIRED[mime];
    else valid = true;
  } else {
    valid = true;
  }
  const o = { json: { valid: valid, file_id: meta.file_id, filename: filename, mime: mime, reason: reason } };
  if (valid && items[k].binary && items[k].binary.data) {
    o.binary = { data: Object.assign({}, items[k].binary.data, { fileName: filename, mimeType: mime }) };
  }
  out.push(o);
}
return out;

const r = $json || {};
const ok = !!(r.id);
let fn = r.title || r.name || '';
if (!fn) { try { fn = $('Validate Doc').item.json.filename; } catch (e) { fn = 'dokument'; } }
return { json: { ok: ok, dropped: !ok, id: r.id || '', url: r.url || '', filename: fn || 'dokument', reason: ok ? '' : 'przesylanie do ClickUp nie powiodlo sie' } };

const r = $json || {};
const err = (r.error && (r.error.message || r.error)) || 'pobranie nie powiodlo sie';
return { json: { ok: false, dropped: true, id: '', url: '', filename: r.filename || 'dokument', reason: 'pobranie: ' + String(err).slice(0,150) } };

const rows = $input.all().map(function(i){ return i.json; }).filter(Boolean);
const doc_attachment_ids = [];
const links = [];
const dropped = [];
for (const r of rows) {
  if (r.ok && r.id) { doc_attachment_ids.push(r.id); links.push({ filename: r.filename, url: r.url }); }
  else { dropped.push({ filename: r.filename, reason: r.reason || 'nieznany' }); }
}
const warnings = [];
if (dropped.length) warnings.push({ source: 'post-reply/doc-delivery', err: 'Nie dostarczono ' + dropped.length + ' pliku(ow): ' + dropped.map(function(d){ return d.filename + ' (' + d.reason + ')'; }).join('; '), severity: 'WARN' });
return [{ json: { doc_attachment_ids: doc_attachment_ids, links: links, dropped: dropped, dropped_count: dropped.length, warnings: warnings } }];

const agg = ($input.first() && $input.first().json) || {};
const fin = $('Finalize Comment').first().json;
const ops = Array.isArray(fin.ops) ? fin.ops.slice() : [];
const links = Array.isArray(agg.links) ? agg.links : [];
const dropped = Array.isArray(agg.dropped) ? agg.dropped : [];
if (links.length || dropped.length) {
  ops.push({ text: '\n' });
  ops.push({ text: 'Załączniki' });
  ops.push({ text: '\n', attributes: { header: 2 } });
  for (const l of links) {
    ops.push({ text: '📎 ' });
    ops.push({ text: l.filename, attributes: { link: l.url } });
    ops.push({ text: '\n', attributes: { list: 'bullet' } });
  }
  for (const d of dropped) {
    ops.push({ text: '⚠️ Nie udało się dołączyć pliku „' + d.filename + '” (plik uszkodzony lub niedostępny).\n', attributes: { italic: true } });
  }
}
return [{ json: { ops: ops, run_payload_bytes: fin.run_payload_bytes, attachment_ids: fin.attachment_ids || [], doc_attachment_ids: agg.doc_attachment_ids || [] } }];
